export class Carrito {
    _id: string;
    emailUsuario: string;
    productos: ProductoCarrito[];
    total: number;

    constructor(){
        this._id = "";
        this.emailUsuario = "";
        this.productos = [];
        this.total = 0;
    }
}


export class ProductoCarrito { 
    nombre: string;
    cantidad: number;
    precio: number;
  
    constructor(nombre:string, cantidad: number, precio: number) {
      this.nombre = nombre;
      this.cantidad = cantidad;
      this.precio = precio;
    }
  }
